command:
$ErrorActionPreference="Stop"
Set-Location -LiteralPath $env:FLYEXPLORER_CANONICAL_CHECKOUT
& git fetch origin --tags --prune
if($LASTEXITCODE -ne 0){throw "tag fetch failed"}
Write-Host "===== TAGS ====="
$tags=@(& git tag --list --sort=version:refname)
if($LASTEXITCODE -ne 0){throw "tag list failed"}
$tags | ForEach-Object { Write-Host ("TAG="+$_) }
Write-Host "===== V1 TAG RESOLUTION ====="
$v1=@(& git rev-parse -q --verify "refs/tags/v1.0.0.0" 2>$null)
$v1Exists=($LASTEXITCODE -eq 0)
Write-Host ("V1_TAG_EXISTS="+$v1Exists)
if($v1Exists){
  Write-Host ("V1_TAG_OBJECT="+($v1 -join ""))
  $v1Commit=(& git rev-parse "refs/tags/v1.0.0.0^{commit}").Trim()
  Write-Host ("V1_TAG_COMMIT="+$v1Commit)
}
Write-Host "===== RULESETS ====="
& gh api repos/tngkrwlsmd/flyExplorer/rulesets --jq '.[] | {id,name,target,enforcement,bypass_actors,conditions,rules}'
if($LASTEXITCODE -ne 0){throw "ruleset query failed"}
Write-Host "===== IMMUTABLE RELEASES ====="
$immutableOutput=& gh api repos/tngkrwlsmd/flyExplorer/immutable-releases 2>&1
$immutableCode=$LASTEXITCODE
if($immutableCode -eq 0){
  Write-Host "IMMUTABLE_RELEASES_ENABLED=true"
  $immutableOutput | ForEach-Object { Write-Host $_ }
} else {
  Write-Host "IMMUTABLE_RELEASES_ENABLED=false"
  $immutableOutput | ForEach-Object { Write-Host ("IMMUTABLE_RELEASES_QUERY="+$_) }
}
Write-Host "===== REPOSITORY ====="
& gh api repos/tngkrwlsmd/flyExplorer --jq '{visibility,private,default_branch,archived,disabled}'
if($LASTEXITCODE -ne 0){throw "repository metadata query failed"}
